__d(function(e,t,n,i,o,s,a){o.exports={version:"2.3.0",initialScreen:"Home",screens:[{id:"Home",title:"TD Home",showNavigationBar:!1,type:"ContentListScreen",design:"loose",contents:[{type:"Header",headerText:"Transferable Discipleship",subheaderText:"A tool for Simple, Accessible, and Transferable Christian discipleship",lineTexts:["Please select an option below"],design:"title"},{type:"ActionButton",text:"Start Here",action:{type:"navigate",to:"Start Here"}},{type:"ActionButton",text:"Basics",action:{type:"navigate",to:"Basics"}},{type:"ActionButton",text:"Resources",action:{type:"navigate",to:"Resources"}},{type:"ActionButton",text:"About",action:{type:"navigate",to:"About"}}],subscreens:[{id:"Start Here",type:"ContentListScreen",design:"loose",contents:[{type:"Header"},{type:"ActionButton",text:"The Challenge",action:{type:"navigate",to:"The Challenge"}},{type:"ActionButton",text:"Why use TD",action:{type:"navigate",to:"WhyUseTD"}}],subscreens:[{id:"The Challenge",type:"ContentListScreen",design:"loose",contents:[{type:"Header"},{type:"Slide",canClose:!1,contentDesign:"tight",contents:["This section is meant to set the stage for everything that follows by addressing three core questions: Why discipleship matters, what discipleship actually is, and what it will require of you.","Before talking about methods or content, it is important to understand the answer to these questions."]},{type:"ActionButton",text:"Discipleship Is for Every Believer",action:{type:"navigate",to:"DiscipleshipEveryBeliever"}},{type:"ActionButton",text:"So Why Discipleship?",action:{type:"navigate",to:"WhyDiscipleship"}},{type:"ActionButton",text:"The Benefits Are Far-Reaching",action:{type:"navigate",to:"BenefitsFarReaching"}},{type:"ActionButton",text:"What Is Discipleship?",action:{type:"navigate",to:"WhatIsDiscipleship"}},{type:"ActionButton",text:"Expectations",action:{type:"navigate",to:"Expectations"}}],subscreens:[{id:"DiscipleshipEveryBeliever",title:"Discipleship Is for Every Believer",type:"ContentListScreen",contents:[{type:"Header"},{type:"Slide",headerText:"Matthew 28:18\u201320",canClose:!0,contents:[{type:"ScrRangeDisplay",reference:"Matthew 28:18-20",style:{alignSelf:"flex-start",fontStyle:"italic"}}]},{type:"ToggleButton",design:"answer",text:"When you read this passage, what responsibility do you hear Jesus placing on His followers?",altButtons:[{design:"answer",text:"Making disciples is not reserved for \"the experts\". It is the mandate of all believers."}]},{type:"Slide",canClose:!1,contentDesign:"tight",contents:["The pattern that emerges throughout Scripture is disciples who make disciples, who make disciples\u2026"]}]},{id:"WhyDiscipleship",title:"So Why Discipleship?",type:"ContentListScreen",contents:[{type:"Header"},{type:"Slide",canClose:!1,contentDesign:"tight",contents:["Throughout Scripture, discipleship is woven into the story of God's people rather than added later as a program."]},{type:"Slide",headerText:"Acts 1:8",canClose:!0,contents:[{type:"ScrRangeDisplay",reference:"Acts 1:8",style:{alignSelf:"flex-start",fontStyle:"italic"}}]},{type:"ToggleButton",design:"answer",text:"So why discipleship?",altButtons:[{design:"answer",text:"Jesus commanded it."}]},{type:"Slide",headerText:"Luke 2:52",canClose:!0,contents:[{type:"ScrRangeDisplay",reference:"Luke 2:52",style:{alignSelf:"flex-start",fontStyle:"italic"}}]},{type:"ToggleButton",design:"answer",text:"So why discipleship?",altButtons:[{design:"answer",text:"Jesus experienced it."}]},{type:"Slide",headerText:"Mark 3:13\u201319",canClose:!0,contents:[{type:"ScrRangeDisplay",reference:"Mark 3:13-19",style:{alignSelf:"flex-start",fontStyle:"italic"}}]},{type:"ToggleButton",design:"answer",text:"So why discipleship?",altButtons:[{design:"answer",text:"Jesus modeled it with 12."}]},{type:"Slide",headerText:"Genesis 2:15",canClose:!0,contents:[{type:"ScrRangeDisplay",reference:"Genesis 2:15",style:{alignSelf:"flex-start",fontStyle:"italic"}}]},{type:"Slide",headerText:"Genesis 3:8",canClose:!0,contents:[{type:"ScrRangeDisplay",reference:"Genesis 3:8",style:{alignSelf:"flex-start",fontStyle:"italic"}}]},{type:"ToggleButton",design:"answer",text:"So why discipleship?",altButtons:[{design:"answer",text:"We were created for discipleship. Before sin entered the world, Adam did the work God gave him to do and walked in a growing relationship with Him."}]},{type:"Slide",canClose:!1,contentDesign:"tight",contents:["Discipleship reflects God's original design for how people grow and live in relationship with God."]},{type:"QuestionPrompt",text:"Which of these examples most reshapes how you think about discipleship?"}]},{id:"BenefitsFarReaching",title:"The Benefits Are Far-Reaching",type:"ContentListScreen",contents:[{type:"Header"},{type:"Slide",canClose:!1,contentDesign:"tight",contents:["Discipleship shapes more than knowledge. It influences spiritual growth, relationships, and long-term faithfulness."]},{type:"Slide",headerText:"Spiritual Growth",canClose:!1,contentDesign:"tight",contents:["Growth happens most often when faith is practiced, discussed, and lived out with others."]},{type:"Slide",headerText:"Healthy Community",canClose:!1,contentDesign:"tight",contents:["Discipleship fosters deeper relationships marked by honesty, encouragement, and accountability."]},{type:"Slide",headerText:"Giving Away What You Learn",canClose:!1,contentDesign:"tight",contents:["As growth happens, faith is exercised through action and obedience."]},{type:"Slide",headerText:"Leaving a Legacy",canClose:!1,contentDesign:"tight",contents:["Multiplying faith through others allows God's work to continue in and through others."]},{type:"QuestionPrompt",text:"Which of these benefits feels most needed in your life right now?"}]},{id:"WhatIsDiscipleship",title:"What Is Discipleship?",type:"ContentListScreen",contents:[{type:"Header"},{type:"Slide",canClose:!1,contentDesign:"tight",contents:["A disciple is someone who learns how to grow, live, and express the Christian life and then repeats that process with others.","\u2014 Chasing Infinity, Mark Liederbach"]},{type:"Slide",canClose:!1,contentDesign:"tight",contents:["Discipleship is the process of one person helping another live out that reality."]},{type:"Slide",canClose:!1,contentDesign:"tight",contents:["Discipleship includes four main elements:"]},{type:"Slide",headerText:"Content",canClose:!0,contentDesign:"tight",contents:["Growing in relationship with God through the Bible and prayer."]},{type:"Slide",headerText:"Community",canClose:!0,contentDesign:"tight",contents:["Growing in faith is not a solitary experience. Other believers help provide encouragement, perspective, and accountability, especially in areas that are easy to overlook alone."]},{type:"Slide",headerText:"Context",canClose:!0,contentDesign:"tight",contents:["Each person has a unique environment. Classes, clubs, teams, and campus relationships provide opportunities for you to live out and share your faith with people you are uniquely able to reach."]},{type:"Slide",headerText:"Continuation",canClose:!0,contentDesign:"tight",contents:["Discipleship involves investing in others so they can invest in others, allowing faith to continue across generations."]},{type:"QuestionPrompt",text:"Which of these four areas feels most developed for you right now? Which feels least developed?"}]},{id:"Expectations",type:"ContentListScreen",contents:[{type:"Header"},{type:"Slide",canClose:!1,contentDesign:"tight",contents:["Discipleship is simple, but it requires intention and consistency."]},{type:"Slide",canClose:!1,contentDesign:"tight",contents:[{type:"Text",text:"A willingness to grow in biblical foundations in order to pass them on",style:{alignSelf:"flex-start"}},{type:"Text",text:"A willingness to be stretched and challenged",style:{alignSelf:"flex-start"}},{type:"Text",text:"A commitment to meet weekly or bi-weekly, with consistency and respect for time",style:{alignSelf:"flex-start"}},{type:"Text",text:"An understanding that unexpected things happen, but discipleship should be a priority",style:{alignSelf:"flex-start"}},{type:"Text",text:"A willingness to take steps of faith, including learning how to share faith with others",style:{alignSelf:"flex-start"}}]},{type:"QuestionPrompt",text:"Which of these expectations feels most difficult for you right now?"},{type:"QuestionPrompt",text:"Does this sound like something you are willing to commit to?"}]}]},{id:"WhyUseTD",title:"Why use TD",type:"ContentListScreen",design:"loose",contents:[{type:"Header"},{type:"ActionButton",text:"About TD",action:{type:"navigate",to:"StartHereAboutTD"}},{type:"ActionButton",text:"The Why",action:{type:"navigate",to:"StartHereWhy"}},{type:"ActionButton",text:"Biblical Discipleship",action:{type:"navigate",to:"StartHereBiblical"}},{type:"ActionButton",text:"Simple",action:{type:"navigate",to:"StartHereSimple"}},{type:"ActionButton",text:"Accessible",action:{type:"navigate",to:"StartHereAccessible"}},{type:"ActionButton",text:"Transferable",action:{type:"navigate",to:"StartHereTransferable"}},{type:"ActionButton",text:"Material Overview",action:{type:"navigate",to:"StartHereMaterial"}}],subscreens:[{id:"StartHereAboutTD",title:"Why use TD",type:"ContentListScreen",contents:[{type:"Header",headerText:"About TD"},{type:"Slide",canClose:!1,contentDesign:"tight",contents:["Transferable Discipleship is a tool designed to help followers of Jesus engage in discipleship that is simple, accessible, and transferable, providing a solid foundation for the journey of faith."]}]},{id:"StartHereWhy",title:"Why use TD",type:"ContentListScreen",contents:[{type:"Header",headerText:"The Why"},{type:"Slide",canClose:!1,contentDesign:"tight",contents:["Jesus' command, \"Go and make disciples\u2026\" (Matthew 28:19), is a mandate for all believers. We were created to make disciples."]},{type:"QuestionPrompt",text:"When you hear the phrase \"make disciples,\" what comes to mind based on your past experiences?"}]},{id:"StartHereBiblical",title:"Why use TD",type:"ContentListScreen",contents:[{type:"Header",headerText:"Biblical Discipleship"},{type:"Slide",canClose:!1,contentDesign:"tight",contents:["Biblical discipleship is not just about passing along good information. It is about seeing faithfulness and maturity continue from one generation to the next, building the same solid foundation in ways that others can then pass on.","Transferable Discipleship exists to help make that possible by keeping discipleship simple, accessible, and transferable."]},{type:"QuestionPrompt",text:"Why do you think discipleship often stops with one person instead of continuing to others?"}]},{id:"StartHereSimple",title:"Why use TD",type:"ContentListScreen",contents:[{type:"Header",headerText:"Simple"},{type:"Slide",canClose:!1,contentDesign:"tight",contents:["The content is structured in an easy-to-lead format, making it approachable for anyone. Each section is designed to be read together and to naturally spark meaningful discussion, not require expert knowledge or special training."]}]},{id:"StartHereAccessible",title:"Why use TD",type:"ContentListScreen",contents:[{type:"Header",headerText:"Accessible"},{type:"Slide",canClose:!1,contentDesign:"tight",contents:["Discipleship resources can be difficult to find, and even harder to share once the person you have discipled begins discipling someone else. This app removes that barrier.","Transferable Discipleship is free and available to everyone. No cost. No searching. No barriers to entry."]}]},{id:"StartHereTransferable",title:"Why use TD",type:"ContentListScreen",contents:[{type:"Header",headerText:"Transferable"},{type:"Slide",canClose:!1,contentDesign:"tight",contents:["Jesus spent three years discipling a small group of ordinary men, and then sent them out to change the world. They did not keep what He taught and modeled to themselves, and they did not wait until they had everything figured out before helping others."]},{type:"QuestionPrompt",text:"Which of the three values stands out most to you right now: simple, accessible, or transferable? Why?"}]},{id:"StartHereMaterial",title:"Why use TD",type:"ContentListScreen",contents:[{type:"Header",headerText:"Material Overview"},{type:"Slide",canClose:!1,contentDesign:"tight",contents:["This material is not all-inclusive, but it focuses on essential concepts that lay a solid foundation for following Jesus. It is intentionally designed for quick replication, so that after completing these core concepts, anyone should feel prepared to begin discipling someone else."]},{type:"QuestionPrompt",text:"What would change if ordinary believers saw themselves as disciple-makers instead of just participants?"}]}]}]},{id:"Basics",type:"ContentListScreen",contents:[{type:"Header"},{type:"ActionButton",text:"Gospel Review",action:{type:"navigate",to:"Gospel Review"}},{type:"ActionButton",text:"Scripture 1.0",action:{type:"navigate",to:"Scripture 1.0"}},{type:"ActionButton",text:"Assurance of Salvation",action:{type:"navigate",to:"Assurance of Salvation"}},{type:"ActionButton",text:"Holy Spirit",action:{type:"navigate",to:"Holy Spirit"}},{type:"ActionButton",text:"Prayer",action:{type:"navigate",to:"Prayer"}}],subscreens:[{id:"Gospel Review",type:"ContentListScreen",design:"loose",contents:[{type:"Header"},{type:"Slide",canClose:!1,contentDesign:"tight",contents:["Before talking about following Jesus or helping others follow Him, it is important to review the gospel itself. Discipleship flows out of a clear understanding of the relationship between God and humanity, what went wrong, and what God has done to restore that relationship."]},{type:"ActionButton",text:"God and People",action:{type:"navigate",to:"GodAndPeople"}},{type:"ActionButton",text:"God's Plan to Restore the Relationship",action:{type:"navigate",to:"GodsPlanRestore"}},{type:"ActionButton",text:"Half-way Recap",action:{type:"navigate",to:"GospelHalfwayRecap"}},{type:"ActionButton",text:"What Did Jesus Do?",action:{type:"navigate",to:"WhatDidJesusDo"}},{type:"ActionButton",text:"How Were People Made Right with God?",action:{type:"navigate",to:"HowWerePeopleMadeRight"}},{type:"ActionButton",text:"How Should We Respond?",action:{type:"navigate",to:"HowShouldWeRespond"}},{type:"ActionButton",text:"The Whole Story",action:{type:"navigate",to:"TheWholeStory"}}],subscreens:[{id:"GodAndPeople",title:"God and People",type:"ContentListScreen",contents:[{type:"Header"},{type:"QuestionPrompt",text:"How would you describe the relationship between God and people?"},{type:"ScriptureSlide",headerText:"What Is True About God?",scripture:[{reference:"Acts 17:24-27",hiddenButton:{text:"What is true about God from this passage?"},revealedButton:{text:"God created all things, gives life to all things, and He is near."}},{reference:"John 17:3",hiddenButton:{text:"What is true about God from this passage?"},revealedButton:{text:"God is knowable. Eternal life is found in knowing Him."}}]},{type:"QuestionPrompt",text:"Which of these truths about God is most meaningful to you right now?"},{type:"ScriptureSlide",headerText:"What Is True About Humanity?",scripture:[{reference:"Ephesians 2:1-3",hiddenButton:{text:"What is true about humanity from this passage?"},revealedButton:{text:"We are spiritually dead because of sin."}},{reference:"Romans 6:23",hiddenButton:{text:"What is true about humanity from this passage?"},revealedButton:{text:"Sin deserves death."}}]},{type:"Slide",headerText:"How does our sin separate us from God?",canClose:!0,contentDesign:"tight",contents:["Broken trust creates distance in any relationship. Without reconciliation, the relationship remains strained or lost. In a similar way, sin separates us from God. The Bible describes this separation as spiritual death. People were created to live in close relationship with God, but sin cuts us off from the very source of life."]},{type:"QuestionPrompt",text:"When closeness is replaced by distance, how does that affect the relationship?"}]},{id:"GodsPlanRestore",title:"God's Plan to Restore the Relationship",type:"ContentListScreen",contents:[{type:"Header"},{type:"Slide",canClose:!1,contentDesign:"tight",contents:["God did not ignore humanity's separation from Him. From the beginning, He put a plan in place to restore what was broken."]},{type:"ScriptureSlide",headerText:"The Purpose of the Old Testament Law",scripture:{reference:"Romans 3:20-26",hiddenButton:{text:"What is the purpose of the Old Testament law from this passage?"},revealedButton:{text:"The law reveals sin and shows our need for Jesus as our only hope for redemption."}}},{type:"Slide",canClose:!1,contentDesign:"tight",contents:["The law was never meant to save people by acts of obedience. It exposes humanity's inability to meet God's standard and directs attention to the need for a Savior."]},{type:"Slide",headerText:"Key Terms",canClose:!1,contentDesign:"tight",contents:["These terms help explain how God restores the relationship:"]},{type:"Slide",headerText:"Justified",canClose:!0,contentDesign:"tight",contents:["To be declared righteous by God, not because of works, but through faith in Jesus. This declaration removes the guilt and penalty of sin, restoring a right relationship with God."]},{type:"Slide",headerText:"Law",canClose:!0,contentDesign:"tight",contents:["The Old Testament law, comprising religious, civil, and relational regulations (including but not limited to the 10 commandments), guided the Israelites' relationship with God. By obeying these laws, the Israelites demonstrated their love for both God and their neighbors. The Old Testament law today can help Christians gain insight into God's character and recognize our need for Jesus."]},{type:"Slide",headerText:"Righteousness",canClose:!0,contentDesign:"tight",contents:["The state of being morally right and just before God. It is not something that can be earned or achieved through human effort, but rather a gift from God that comes through faith in Jesus Christ."]},{type:"Slide",headerText:"Redemption",canClose:!0,contentDesign:"tight",contents:["God's act of rescuing people from sin and its consequences through the death and resurrection of Jesus. It signifies forgiveness, restoration, and reconciliation with God."]},{type:"Slide",headerText:"Mercy Seat",canClose:!0,contentDesign:"tight",contents:["The solid gold lid that covered the Ark of the Covenant. In the Old Testament it functioned as the place where God's presence dwelt and where atonement was made for the sins of the Israelites. Jesus Christ's death on the cross fulfilled the Old Testament symbolism of the mercy seat, where the High Priest would sprinkle the blood of a sacrificed animal to atone for the sins of the people. Through His sacrificial death, Jesus became the perfect and eternal sacrifice, allowing God to extend mercy and forgiveness to humanity without compromising His righteousness. Unlike the Old Testament system, where only the High Priest could approach the mercy seat once a year, Jesus' sacrifice opened the way for all people to approach God directly through faith. Therefore, Jesus Christ, as the mercy seat, is the focal point of God's redemptive plan, providing the only way for humanity to be reconciled to God and experience His abundant grace and forgiveness."]},{type:"QuestionPrompt",text:"Which of these terms helps you understand the gospel more clearly?"},{type:"QuestionPrompt",text:"How does the law pointing to our need for Jesus reshape the way you read the Old Testament?"}]},{id:"GospelHalfwayRecap",title:"Half-way Recap",type:"ContentListScreen",contents:[{type:"Header"},{type:"Slide",canClose:!1,contentDesign:"tight",contents:["God is near and knowable, the source of all life. People were created to live in close, personal relationship with Him."]},{type:"Slide",canClose:!1,contentDesign:"tight",contents:["God is perfectly holy, and we have all failed to meet His perfect standard."]},{type:"Slide",canClose:!1,contentDesign:"tight",contents:["Our sin has separated us from Him."]},{type:"Slide",canClose:!1,contentDesign:"tight",contents:["Yet God did not leave humanity in that condition; He revealed our need and began preparing the way for restoration."]}]},{id:"WhatDidJesusDo",title:"What Did Jesus Do?",type:"ContentListScreen",contents:[{type:"Header"},{type:"Slide",canClose:!1,contentDesign:"tight",contents:["Jesus is the central figure in God's plan to restore all things."]},{type:"ScriptureSlide",scripture:{reference:"Romans 5:8",hiddenButton:{text:"What did Jesus do?"},revealedButton:{text:"Jesus died in our place."}}},{type:"ScriptureSlide",scripture:{reference:"Romans 5:18",hiddenButton:{text:"What did Jesus do?"},revealedButton:{text:"Through Him we are made righteous."}}},{type:"ScriptureSlide",scripture:{reference:"1 Corinthians 15:3-8",hiddenButton:{text:"What did Jesus do?"},revealedButton:{text:"Jesus died for sins and proved His power through resurrection."}}},{type:"ScriptureSlide",scripture:{reference:"2 Corinthians 5:21",hiddenButton:{text:"What did Jesus do?"},revealedButton:{text:"Jesus took our sin and gave us His righteousness in exchange."}}},{type:"ScriptureSlide",scripture:{reference:"John 14:6",hiddenButton:{text:"What did Jesus do?"},revealedButton:{text:"Jesus is the only way to experience reconciliation with God."}}},{type:"QuestionPrompt",text:"Which aspect of what Jesus did stands out most to you right now?"}]},{id:"HowWerePeopleMadeRight",title:"How Were People Made Right with God?",type:"ContentListScreen",contents:[{type:"Header"},{type:"ScriptureSlide",scripture:[{reference:"Romans 4:1-3",hiddenButton:{text:"How were people made right with God in the old testament?"},revealedButton:{text:"Faith in Jesus, not works."}},{reference:"Ephesians 2:4-5"},{reference:"Ephesians 2:8-9",hiddenButton:{text:"How are people made right with God today?"},revealedButton:{text:"Faith in Jesus, not works."}}]}]},{id:"HowShouldWeRespond",title:"How Should We Respond?",type:"ContentListScreen",contents:[{type:"Header"},{type:"ScriptureSlide",scripture:{reference:"John 3:18",hiddenButton:{text:"Why is a response needed?"},revealedButton:{text:"Apart from Jesus you are condemned already."}}},{type:"Slide",canClose:!1,contentDesign:"tight",contents:["The gospel requires a response. Indifference is choosing unbelief."]},{type:"Slide",headerText:"Key Terms",canClose:!1,contentDesign:"tight",contents:["These terms help explain the response to the gospel:"]},{type:"Slide",headerText:"Repentance",canClose:!0,contentDesign:"tight",contents:["A sincere turning away from sin and toward God. It involves recognizing one's wrongdoing, feeling remorse, and changing one's behavior and heart."]},{type:"Slide",headerText:"Belief",canClose:!0,contentDesign:"tight",contents:["Not just intellectual ascent but also a heartfelt commitment that leads to obedience and trust."]},{type:"ScriptureSlide",scripture:{reference:"Romans 10:9-10",hiddenButton:{text:"How should we respond?"},revealedButton:{text:"Confess and believe."}}},{type:"ScriptureSlide",scripture:[{reference:"Mark 1:15",hiddenButton:{text:"How should we respond?"},revealedButton:{text:"Repent and believe the gospel."}},{reference:"Acts 3:19",hiddenButton:{text:"How should we respond?"},revealedButton:{text:"Repent and turn toward God."}}]},{type:"ScriptureSlide",scripture:{reference:"2 Corinthians 5:15",hiddenButton:{text:"How should we respond?"},revealedButton:{text:"Live with a new purpose."}}},{type:"QuestionPrompt",text:"Which part of this response feels most challenging or most personal to you?"},{type:"QuestionPrompt",text:"Have you ever made that commitment?"}]},{id:"TheWholeStory",title:"The Whole Story",type:"ContentListScreen",contents:[{type:"Header"},{type:"Slide",canClose:!1,contentDesign:"tight",contents:["God is near and knowable, the source of all life. People were created to live in close, personal relationship with Him. (Acts 17:24\u201327)"]},{type:"Slide",canClose:!1,contentDesign:"tight",contents:["God is perfectly holy, and we have all failed to meet His perfect standard. (Romans 3:23)"]},{type:"Slide",canClose:!1,contentDesign:"tight",contents:["Sin caused us to be separated from God. (Romans 6:23)"]},{type:"Slide",canClose:!1,contentDesign:"tight",contents:["God did not leave humanity in that condition; He revealed our need and began preparing the way for restoration. (Romans 3:20\u201326; Romans 4:1\u20133; Ephesians 2:8\u20139)"]},{type:"Slide",canClose:!1,contentDesign:"tight",contents:["Jesus lived perfectly, died in humanity's place, and took away our sin and gave us His righteousness. (Romans 5:6\u20138; Romans 5:18\u201319; John 14:6; 2 Corinthians 5:21)"]},{type:"Slide",canClose:!1,contentDesign:"tight",contents:["All who repent and believe receive eternal life. (John 3:16\u201318; Romans 10:9\u201310)"]},{type:"Slide",canClose:!1,contentDesign:"tight",contents:["Life now has a new purpose, lived for God rather than self. (2 Corinthians 5:15)"]},{type:"QuestionPrompt",text:"Final Question: How would you explain this story to someone else in your own words?"}]}]},{id:"Scripture 1.0",type:"ContentListScreen",design:"loose",contents:[{type:"Header"},{type:"ActionButton",text:"Introduction",action:{type:"navigate",to:"Introduction"}},{type:"ActionButton",text:"What Is Scripture?",action:{type:"navigate",to:"WhatIsScripture"}},{type:"ActionButton",text:"Why Should I Read Scripture?",action:{type:"navigate",to:"WhyReadScripture"}},{type:"ActionButton",text:"Half-way Recap",action:{type:"navigate",to:"ScriptureHalfwayRecap"}},{type:"ActionButton",text:"What Should We Do with Scripture?",action:{type:"navigate",to:"WhatShouldWeDo"}},{type:"ActionButton",text:"How Does Scripture Affect My Life?",action:{type:"navigate",to:"HowScriptureAffectsLife"}},{type:"ActionButton",text:"What Does Daily Time with God Look Like?",action:{type:"navigate",to:"DailyTimeWithGod"}}],subscreens:[{id:"Introduction",type:"ContentListScreen",contents:[{type:"Header"},{type:"Slide",canClose:!1,contentDesign:"tight",contents:["Scripture 1.0 is not intended to answer every question about the Bible. Later sections will address the reliability of Scripture and practical methods for deeper study.","The purpose of this section is simple. By looking directly at Scripture, it aims to show why reading the Bible matters, how God uses it in our lives, and how it shapes daily life and faith. The goal is to help you see the value of engaging Scripture regularly and to give you a starting point for doing so."]},{type:"Slide",canClose:!1,contentDesign:"tight",contents:[{type:"Text",text:"\"The Bible is the inevitable outcome of God's continuous speech. It is the infallible declaration of His mind for us, put into our familiar human words.\"",style:{fontStyle:"italic"}},{type:"Text",text:"\u2014 A. W. Tozer, The Pursuit of God",style:{textAlign:"right",fontStyle:"italic"}}]},{type:"QuestionPrompt",text:"What do you think about this quote from Tozer?"}]},{id:"WhatIsScripture",title:"What Is Scripture?",type:"ContentListScreen",contents:[{type:"Header"},{type:"Slide",canClose:!1,contentDesign:"tight",contents:[{type:"Text",text:"",segments:[{text:"Scripture refers to the sacred writings of Christianity contained in the Bible. It consists of the 66 books of the Old and New Testaments and records God's revelation of "},{text:"Himself",style:{fontWeight:"700"}},{text:", "},{text:"His purposes",style:{fontWeight:"700"}},{text:", and "},{text:"His work",style:{fontWeight:"700"}},{text:" in the world."}]}]},{type:"QuestionPrompt",text:"Why is it important that scripture addresses God's revelation of 1. Himself 2. His purposes 3. His work in the world?"},{type:"QuestionPrompt",text:"Beyond understanding God, His purposes, and His work, what other questions do you find yourself wanting answers to?"},{type:"ScriptureSlide",scripture:{reference:"2 Timothy 3:16",hiddenButton:{text:"What does this passage teach you about scripture?"},revealedButton:{text:"Scripture is inspired by God."}}},{type:"ScriptureSlide",scripture:{reference:"Hebrews 4:12",hiddenButton:{text:"What does this passage teach you about scripture?"},revealedButton:{text:"God's word is living and active."}}},{type:"Slide",canClose:!1,contentDesign:"tight",contents:["Scripture is not merely informational. It is God communicating with people through human language."]},{type:"Slide",canClose:!1,contentDesign:"tight",contents:["When I first started playing guitar, I had to concentrate on every detail, finger placement, chords, timing. It was all about learning information. But over time, through repetition, it became muscle memory. I didn't have to think about every movement. I could listen, respond, and actually make music.","In a similar way, Scripture is more than information to master. As we grow in it, we begin to recognize God's voice and respond to Him. It moves from something we study to someone we listen to."]},{type:"QuestionPrompt",text:"When you think about the Bible, do you tend to see it more as information to learn or a voice to listen to? Why?"}]},{id:"WhyReadScripture",title:"Why Should I Read Scripture?",type:"ContentListScreen",contents:[{type:"Header"},{type:"Slide",canClose:!1,contentDesign:"tight",contents:["Scripture consistently describes its own purpose and value."]},{type:"ScriptureQuestionList",question:"What are the benefits of reading scripture?",slides:[{scripture:{reference:"2 Timothy 3:14-17",revealedButton:{text:"Scripture makes a person wise for salvation and is useful for teaching, rebuking, correcting, and training in righteousness, equipping believers for every good work."}}},{scripture:{reference:"Romans 15:4",revealedButton:{text:"What was written previously was written for instruction, producing endurance and encouragement and giving hope."}}},{scripture:{reference:"Psalm 19:7-11",revealedButton:{text:"God's instruction is perfect and restores life. His rules are trustworthy and make the inexperienced wise. They are right, pure, enduring, and righteous altogether."}}},{scripture:{reference:"John 17:17",revealedButton:{text:"God's word is truth."}}}]},{type:"Slide",canClose:!1,contentDesign:"tight",contents:["Scripture shapes what we believe, how we live, and how we endure."]},{type:"QuestionPrompt",text:"Which of these benefits do you most need right now: wisdom, hope, encouragement, or direction?"}]},{id:"ScriptureHalfwayRecap",title:"Half-way Recap",type:"ContentListScreen",contents:[{type:"Header"},{type:"Slide",canClose:!1,contentDesign:"tight",contents:["Scripture is God's communication to us. Through the Bible, He reveals who He is, what He is doing, and how we are meant to live in response."]},{type:"Slide",canClose:!1,contentDesign:"tight",contents:["It is not just information to learn, but a living and active way God speaks and shapes our lives."]},{type:"Slide",canClose:!1,contentDesign:"tight",contents:["As we engage it regularly, we grow from simply understanding it to recognizing and responding to God's voice."]},{type:"Slide",canClose:!1,contentDesign:"tight",contents:["Scripture ultimately gives wisdom, truth, hope, and direction, equipping us to follow God in everyday life."]}]},{id:"WhatShouldWeDo",title:"What Should We Do with Scripture?",type:"ContentListScreen",contents:[{type:"Header"},{type:"Slide",canClose:!1,contentDesign:"tight",contents:["Scripture is meant to be engaged, not merely read."]},{type:"ScriptureSlide",scripture:{reference:"Psalm 1:1-3",hiddenButton:{text:"How should we engage with scripture?"},revealedButton:{text:"The blessed person delights in the law of the Lord and meditates on it day and night."}}},{type:"Slide",headerText:"Meditation Defined",canClose:!0,contentDesign:"tight",contents:["When you see the word meditate in the Old Testament it is the Hebrew word \"Hagad\" which means \"to moan, growl, or make a noise.\" This is not silent contemplative stuff we're talking about here. Rabbi Samson Hirsh explains that \"hagad is that active thinking which demands expression.\" So Biblical meditation means that you think about what you read and as you think about it you share what you are learning with others."]},{type:"ScriptureQuestionList",question:"How should we engage with scripture?",slides:[{scripture:{reference:"Matthew 7:24-27",revealedButton:{text:"Hearing God's words is not enough. Wisdom comes from putting them into practice."}}},{scripture:{reference:"John 8:31-32",revealedButton:{text:"Continuing in Jesus' word leads to freedom."}}}]},{type:"QuestionPrompt",text:"What prevents you from actively engaging with scripture as you read it?"}]},{id:"HowScriptureAffectsLife",title:"How Does Scripture Affect My Life?",type:"ContentListScreen",contents:[{type:"Header"},{type:"Slide",canClose:!1,contentDesign:"tight",contents:["Scripture does not remain external. It reshapes the inner life and outward actions."]},{type:"ScriptureSlide",scripture:{reference:"Psalm 119:11",hiddenButton:{text:"How does scripture affect my life?"},revealedButton:{text:"God's word is stored in the heart to guard against sin."}}},{type:"QuestionPrompt",text:"How could internalizing scripture help shape your daily choices?"},{type:"ScriptureSlide",scripture:{reference:"Psalm 40:8",hiddenButton:{text:"How does scripture affect my life?"},revealedButton:{text:"God's law within the heart produces a desire to do His will."}}},{type:"QuestionPrompt",text:"How does Scripture influence what you want, not just what you do?"},{type:"ScriptureSlide",scripture:{reference:"Deuteronomy 11:18-20",hiddenButton:{text:"How does scripture affect my life?"},revealedButton:{text:"God's words are meant to shape thoughts, actions, conversations, and daily rhythms."}}},{type:"Slide",canClose:!1,contentDesign:"tight",contents:["Storing up scripture in your heart, letting it get down deep into your soul changes you. It begins to be shown in your actions (hands). It becomes the lens through which you see the world (between your eyes). You pass it on to your family in all parts of your daily life (talking, sitting, walking, the last thing you think about before sleep, the first thing you think about when you wake). All areas of your life are marked by these truths."]}]},{id:"DailyTimeWithGod",title:"What Does Daily Time with God Look Like?",type:"ContentListScreen",contents:[{type:"Header"},{type:"Slide",canClose:!1,contentDesign:"tight",contents:["The Bible is a big book and it takes time to absorb it all. That is why it is important to develop a daily discipline of reading scripture. Here are some questions to put you on the right track."]},{type:"Slide",headerText:"When?",canClose:!0,contentDesign:"tight",contents:["Choose a time you can realistically maintain. Consistency matters more than duration. Guard that time."]},{type:"QuestionPrompt",text:"What time of day are you most attentive and least distracted?"},{type:"Slide",headerText:"Where?",canClose:!0,contentDesign:"tight",contents:["Location matters more than it seems. A consistent place helps form habits and reduces distractions. Choose a space where focus is possible."]},{type:"Slide",headerText:"What?",canClose:!0,contentDesign:"tight",contents:["Have a plan. Decide in advance what you will read so the decision does not become a barrier. A plan that includes all of Scripture helps avoid only returning to familiar passages."]},{type:"QuestionPrompt",text:"What kind of plan would be both challenging and sustainable for you?"},{type:"Slide",headerText:"How?",canClose:!0,contentDesign:"tight",contents:["Consider what will support faithfulness.","Are there any resources you need to set you up for success?","Do you need to buy a new bible? A journal? Highlighters? Who will keep you accountable and who can you talk with about the things you are learning each day?"]},{type:"QuestionPrompt",text:"What is one practical step you could take this week to make daily Scripture engagement more realistic?"}]}]},{id:"Assurance of Salvation",type:"ContentListScreen",design:"loose",contents:[{type:"Header"},{type:"ActionButton",text:"Can I know that my faith is secure?",action:{type:"navigate",to:"CanKnowFaithSecure"}},{type:"ActionButton",text:"What does a saved person's life begin to look like?",action:{type:"navigate",to:"SavedPersonLife"}},{type:"ActionButton",text:"How can I recognize the evidence of salvation in my life?",action:{type:"navigate",to:"EvidenceOfSalvation"}},{type:"ActionButton",text:"Half-way Recap",action:{type:"navigate",to:"AssuranceHalfwayRecap"}},{type:"ActionButton",text:"Can anything cause me to lose my salvation?",action:{type:"navigate",to:"CanLoseSalvation"}},{type:"ActionButton",text:"Was Jesus' sacrifice enough?",action:{type:"navigate",to:"WasJesusSacrificeEnough"}}],subscreens:[{id:"CanKnowFaithSecure",title:"Can I know that my faith is secure?",type:"ContentListScreen",contents:[{type:"Header"},{type:"QuestionPrompt",text:"Question: If a friend asked you if they can know that their salvation is secure, what would you tell them?"},{type:"ScriptureSlide",scripture:{reference:"1 John 5:12-13",hiddenButton:{text:"Can you know that your faith is secure?"},revealedButton:{text:"You CAN know your faith is secure."}}},{type:"Slide",canClose:!1,contentDesign:"tight",contents:["John writes so believers may know they have eternal life. Assurance is grounded in who Jesus is and what He has done, not in our changing emotions or our performance before God."]},{type:"ScriptureSlide",scripture:{reference:"2 Corinthians 13:5",hiddenButton:{text:"What does healthy self-examination look like for a believer?"},revealedButton:{text:"Self-examination is meant to invite honest reflection, not fear. Scripture encourages believers to look at their lives in light of Christ's presence, not to constantly question whether God has abandoned them."}}}]},{id:"SavedPersonLife",title:"What does a saved person's life begin to look like?",type:"ContentListScreen",contents:[{type:"Header"},{type:"Slide",canClose:!1,contentDesign:"tight",contents:["Salvation restores the relationship. Growth reshapes the life. Reconciliation happens immediately; transformation happens over time. It's not instant perfection, it's a new direction."]},{type:"ScriptureSlide",scripture:{reference:"2 Corinthians 5:17",hiddenButton:{text:"What changes when someone is \"in Christ\"?"},revealedButton:{text:"A new identity forms the foundation for a new way of life."}}},{type:"ScriptureSlide",scripture:{reference:"Ephesians 4:22-24",hiddenButton:{text:"What ongoing process is described in the life of a believer?"},revealedButton:{text:"Growth in Christ involves an ongoing process of putting off your old ways and putting on what reflects new life."}}},{type:"QuestionPrompt",text:"Question: What evidence of growth have you seen in your life, even if it has been slow?"},{type:"QuestionPrompt",text:"Question: Where do you still feel tension between old patterns and new desires?"}]},{id:"EvidenceOfSalvation",title:"How can I recognize the evidence of salvation in my life?",type:"ContentListScreen",contents:[{type:"Header"},{type:"ScriptureSlide",scripture:{reference:"1 John 2:3-6",hiddenButton:{text:"How can I recognize the evidence of salvation in my life?"},revealedButton:{text:"Our life begins to be marked by obedience to God's desire for our life."}}},{type:"ScriptureSlide",scripture:{reference:"1 John 3:6"}},{type:"ScriptureQuestionList",question:"How can I recognize the evidence of salvation in my life?",slides:[{scripture:{reference:"1 John 3:9-10",revealedButton:{text:"This does not mean believers never sin. It means sin no longer defines the pattern of their lives."}}},{scripture:{reference:"1 John 3:14",revealedButton:{text:"We begin to have more love toward other people."}}},{scripture:{reference:"1 John 3:24",revealedButton:{text:"His Spirit lives in us."}}}]},{type:"QuestionPrompt",text:"Question: Which of these evidences encourages you most?"}]},{id:"AssuranceHalfwayRecap",title:"Half-way Recap",type:"ContentListScreen",contents:[{type:"Header"},{type:"Slide",canClose:!1,contentDesign:"tight",contents:["Assurance of salvation is grounded in Jesus, not in our performance or emotions. Through Him, we can know we have eternal life. At the same time, Scripture invites honest self-examination, not to create fear, but to help us recognize Christ's work in us."]},{type:"Slide",canClose:!1,contentDesign:"tight",contents:["Salvation immediately restores our relationship with God, and over time, that new identity begins to reshape our lives. Growth is not about instant perfection, but a new direction marked by increasing obedience, a changing pattern of life, love for others, and the presence of the Holy Spirit."]}]},{id:"CanLoseSalvation",title:"Can anything cause me to lose my salvation?",type:"ContentListScreen",contents:[{type:"Header"},{type:"ScriptureQuestionList",question:"Can anything cause me to lose my salvation?",slides:[{scripture:{reference:"John 10:27-29",revealedButton:{text:"No. We are safely held in the hands of God."}}},{scripture:{reference:"Ephesians 1:13-14",revealedButton:{text:"No. We are sealed by the Holy Spirit."}}}]},{type:"Slide",canClose:!1,contentDesign:"tight",contents:["In the ancient world, a seal represented ownership, protection, and authenticity. The Spirit's seal points to God's commitment to keep and protect us as His own."]},{type:"ScriptureQuestionList",question:"Can anything cause me to lose my salvation?",slides:[{scripture:{reference:"Romans 8:16",revealedButton:{text:"No. The Spirit bears witness that we are God's children."}}},{scripture:{reference:"John 6:37",revealedButton:{text:"No. God does not disown us."}}},{scripture:{reference:"Romans 8:38-39",revealedButton:{text:"No. Nothing can separate us from God."}}}]},{type:"Slide",canClose:!1,contentDesign:"tight",contents:[{type:"Text",text:"",segments:[{text:"Scripture strongly supports that salvation is received as a gift and not earned by effort. Some hold that a person could later reject that gift. This is a secondary issue and should be held with humility. Regardless of one's view. "},{text:"Seasons of doubt or failure do not undo genuine faith.",style:{fontWeight:"700"}},{text:" Be encouraged, a desire to know God reflects that you are not walking away from Him. And you can have confidence that He is NOT walking away from you!"}]}]}]},{id:"WasJesusSacrificeEnough",title:"Was Jesus' sacrifice enough?",type:"ContentListScreen",contents:[{type:"Header"},{type:"ScriptureQuestionList",question:"Was Jesus' sacrifice enough?",slides:[{scripture:{reference:"Colossians 2:14",revealedButton:{text:"He has taken away the debt we owed because of our sin."}}},{scripture:{reference:"Hebrews 10:11-18",revealedButton:{text:"Jesus' one-time sacrifice was enough."}}}]},{type:"Slide",headerText:"From kaphar to lutrosis",canClose:!1,contentDesign:"tight",contents:["Under the Old Covenant, the Hebrew word kaphar in Leviticus 16:17 means \"to cover.\" Sin was addressed temporarily, not removed. Under the New Covenant, Hebrews 9:11\u201312 uses the Greek word lutrosis, meaning redemption or release by payment of a ransom. Sin is not covered but paid for. This shift in language reflects a shift in reality. The Old Covenant is now obsolete because it has been fulfilled (Hebrews 8:13). Jesus' sacrifice removed the record of sin completely. As Hebrews 10:17 says, \"Their sins and their lawless deeds I will remember no more.\" Believers have moved from death to life, not by effort, but by the finished work of Christ."]},{type:"QuestionPrompt",text:"Question: How would your life look different if you were confident that God will never let you go?"}]}]},{id:"Holy Spirit",type:"ContentListScreen",design:"loose",contents:[{type:"Header"},{type:"ActionButton",text:"Opening Reflection",action:{type:"navigate",to:"OpeningReflection"}},{type:"ActionButton",text:"Who Is the Holy Spirit?",action:{type:"navigate",to:"WhoIsHolySpirit"}},{type:"ActionButton",text:"What Does the Holy Spirit Do?",action:{type:"navigate",to:"WhatDoesHolySpiritDo"}},{type:"ActionButton",text:"Half-way Recap",action:{type:"navigate",to:"HolySpiritHalfwayRecap"}},{type:"ActionButton",text:"What is the ongoing role of the Spirit?",action:{type:"navigate",to:"SpiritsOngoingRole"}},{type:"ActionButton",text:"How Do We Respond to the Holy Spirit?",action:{type:"navigate",to:"HowDoWeRespond"}},{type:"ActionButton",text:"God's Invitation: Be Filled With the Spirit",action:{type:"navigate",to:"BeFilledWithSpirit"}},{type:"ActionButton",text:"Summary: Life in the Spirit",action:{type:"navigate",to:"SummaryLifeInSpirit"}},{type:"ActionButton",text:"Spiritual Breathing",action:{type:"navigate",to:"SpiritualBreathing"}}],subscreens:[{id:"OpeningReflection",title:"Opening Reflection",type:"ContentListScreen",contents:[{type:"Header"},{type:"QuestionPrompt",text:"How have you experienced teaching or conversation around the Holy Spirit in the past?"},{type:"Slide",canClose:!1,contentDesign:"tight",contents:["Many Christians tend to approach the Holy Spirit from one of two extremes.","On one side are those who strongly emphasize the gifts of the Spirit, such as tongues or miracles. At times, this emphasis can unintentionally alienate others or make people feel pressured or uncomfortable. A former pastor of mine used to say, \"The Holy Spirit exists to make you holy, not to make you weird.\"","On the other side are those who, often because of past experiences or perceived baggage, largely avoid the topic of the Holy Spirit altogether. This approach can become highly intellectual, where faith is discussed but the Spirit's active role in daily life is minimized.","Cru has historically sought a healthier middle ground. The Spirit is neither ignored nor sensationalized. Instead, the focus is placed on learning how to depend on the Holy Spirit in everyday life. Bill Bright, Cru's founder, was known for saying that the most important thing he could teach a Christian was how to walk in the power of the Spirit."]},{type:"QuestionPrompt",text:"Which of these two tendencies do you resonate with more, and why?"},{type:"Slide",canClose:!1,contentDesign:"tight",contents:["Our goal here is to understand the Holy Spirit biblically and practically, without drifting toward either extreme."]}]},{id:"WhoIsHolySpirit",title:"Who Is the Holy Spirit?",type:"ContentListScreen",contents:[{type:"Header"},{type:"Slide",canClose:!1,contentDesign:"tight",contents:["The Holy Spirit is not an impersonal force or influence. The Spirit is fully God and has been active from the very beginning."]},{type:"ScriptureSlide",scripture:{reference:"Genesis 1:1-2",hiddenButton:{text:"What was the Spirit's involvement at creation?"},revealedButton:{text:"The Spirit of God was present and active in creation."}}},{type:"ScriptureSlide",scripture:{reference:"2 Corinthians 3:17",hiddenButton:{text:"What is the nature of the Spirit?"},revealedButton:{text:"\"Now the Lord is the Spirit, and where the Spirit of the Lord is present, there is freedom.\""}}},{type:"ScriptureSlide",scripture:{reference:"Matthew 3:16-17",hiddenButton:{text:"What stands out here about Father, Son, and Spirit?"},revealedButton:{text:"At Jesus' baptism, the Father speaks, the Son is baptized, and the Spirit descends, revealing the triune nature of God."}}},{type:"QuestionPrompt",text:"Why does it matter that the Holy Spirit is fully God and not merely a force or feeling?"}]},{id:"WhatDoesHolySpiritDo",title:"What Does the Holy Spirit Do?",type:"ContentListScreen",contents:[{type:"Header"},{type:"Slide",canClose:!1,contentDesign:"tight",contents:["The Holy Spirit plays an essential role in both salvation and ongoing growth."]},{type:"ScriptureSlide",scripture:{reference:"Acts 2:38",hiddenButton:{text:"When does someone receive the Holy Spirit?"},revealedButton:{text:"The Spirit is received when someone places faith in Jesus."}}},{type:"ScriptureQuestionList",question:"What does the Holy Spirit do?",slides:[{scripture:{reference:"Romans 5:5",revealedButton:{text:"God's love is poured out in our hearts through the Holy Spirit."}}},{scripture:{reference:"Ephesians 3:16",revealedButton:{text:"The Spirit strengthens us in our inner being."}}},{scripture:{reference:"John 14:25-26",revealedButton:{text:"The Spirit teaches and reminds us of Jesus' words."}}},{scripture:{reference:"1 Corinthians 2:10-12",revealedButton:{text:"The Spirit helps us understand what God has freely given us."}}},{scripture:{reference:"John 16:8",revealedButton:{text:"The Spirit convicts us of sin."}}},{scripture:{reference:"John 16:13-14",revealedButton:{text:"The Spirit guides believers into truth and points attention to Jesus."}}},{scripture:{reference:"Acts 1:8",revealedButton:{text:"The Spirit empowers believers to be witnesses."}}}]},{type:"QuestionPrompt",text:"Which of these roles of the Holy Spirit feels most relevant to your life right now?"}]},{id:"HolySpiritHalfwayRecap",title:"Half-way Recap",type:"ContentListScreen",contents:[{type:"Header"},{type:"Slide",canClose:!1,contentDesign:"tight",contents:["The Holy Spirit is not distant or impersonal. He is fully God, active from creation onward, and personally involved in the lives of believers today."]},{type:"Slide",canClose:!1,contentDesign:"tight",contents:["The Spirit teaches, strengthens, guides, comforts, convicts, and empowers believers to live for Jesus. Christianity was never meant to be lived through human effort alone. God gives His Spirit so believers can know Him, understand truth, and walk in dependence on Him daily."]},{type:"QuestionPrompt",text:"Which role of the Holy Spirit feels most meaningful or needed in your life right now?"},{type:"QuestionPrompt",text:"Which aspect of the Spirit's work is easiest for you to forget in daily life?"}]},{id:"SpiritsOngoingRole",title:"What is the ongoing role of the Spirit?",type:"ContentListScreen",contents:[{type:"Header"},{type:"ScriptureQuestionList",question:"What is the ongoing role of the Spirit?",slides:[{scripture:{reference:"2 Peter 1:20-21",revealedButton:{text:"Scripture comes from God as people were carried along by the Holy Spirit."}}},{scripture:{reference:"Ephesians 1:13-14",revealedButton:{text:"The Spirit seals believers as a guarantee of their inheritance."}}},{scripture:{reference:"2 Timothy 1:13-14",revealedButton:{text:"The Spirit helps guard the truth entrusted to us."}}},{scripture:{reference:"Ezekiel 36:26-27",revealedButton:{text:"God promises to put His Spirit within His people."}}},{scripture:{reference:"1 Corinthians 3:16",revealedButton:{text:"Believers are God's temple, and God's Spirit lives in them."}}}]},{type:"QuestionPrompt",text:"How does knowing the Spirit lives in you change the way you think about obedience and faithfulness?"}]},{id:"HowDoWeRespond",title:"How Do We Respond to the Holy Spirit?",type:"ContentListScreen",contents:[{type:"Header"},{type:"ScriptureSlide",scripture:{reference:"Galatians 5:16-25",hiddenButton:{text:"How should we respond to the Holy Spirit?"},revealedButton:{text:"Believers are called to walk by the Spirit rather than the flesh."}}},{type:"QuestionPrompt",text:"What does it take for a healthy plant to produce fruit?"},{type:"Slide",canClose:!1,contentDesign:"tight",contents:["Fruit is the natural result of life and health. A plant does not force fruit to grow; it produces fruit because it is rooted, nourished, and alive. In the same way, the fruit of the Spirit is the result of walking in step with the Spirit.","By contrast, Scripture speaks of \"deeds of the flesh.\" Deeds begin with temptation and involve choice. Sin follows a familiar pattern:","Temptation","Mental agreement","Action","Temporary gratification","Guilt","Shame","Hiding","Self-condemnation","Confession","Repentance","Restoration","Not every step must happen. At any point, repentance can interrupt the spiral. The longer someone remains in shame and hiding, the more sin maintains its grip. Life in the Spirit invites us out of the spiral and back into freedom."]},{type:"QuestionPrompt",text:"Where do you most often notice temptation gaining momentum in your life?"}]},{id:"BeFilledWithSpirit",title:"God's Invitation: Be Filled With the Spirit",type:"ContentListScreen",contents:[{type:"Header"},{type:"ScriptureSlide",scripture:{reference:"Ephesians 5:18"}},{type:"QuestionPrompt",text:"What do you think it means to be filled with the Spirit?"},{type:"Slide",canClose:!1,contentDesign:"tight",contents:["In this passage, \"filled\" does not mean like water poured into a cup. The image is closer to wind filling a sail. The Greek word pneuma means spirit, wind, or breath. To be filled with the Spirit is to be moved and directed by Him.","The goal is not to create spiritual power, but to position ourselves to receive it. Just as a sail must be adjusted to catch the wind, our lives must be oriented toward God's purposes with openness and surrender."]}]},{id:"SummaryLifeInSpirit",title:"Summary: Life in the Spirit",type:"ContentListScreen",contents:[{type:"Header"},{type:"ScriptureSlide",scripture:{reference:"Romans 8:1-2",answerInSlide:"Life in the Spirit brings freedom."}},{type:"ScriptureSlide",scripture:{reference:"Romans 8:3-4",answerInSlide:"God enables believers to live according to the Spirit."}},{type:"ScriptureSlide",scripture:{reference:"Romans 8:5-11",answerInSlide:"The Spirit gives life."}},{type:"ScriptureSlide",scripture:{reference:"Romans 8:12-13",answerInSlide:"By the Spirit, believers put sin to death."}},{type:"ScriptureSlide",scripture:{reference:"Romans 8:14-16",answerInSlide:"The Spirit brings assurance of belonging to God's family."}}]},{id:"SpiritualBreathing",title:"Spiritual Breathing",type:"ContentListScreen",contents:[{type:"Header"},{type:"Slide",canClose:!1,contentDesign:"tight",contents:["A practical exercise for daily dependence"]},{type:"Slide",headerText:"Exhale: Confession",canClose:!1,contentDesign:"tight",contents:["Agree with God about sin and acknowledge the need for His forgiveness.",{type:"ScrRangeDisplay",reference:"1 John 1:9",style:{alignSelf:"flex-start",fontStyle:"italic"}},"Repent, allowing God to reshape heart, mind, and direction."]},{type:"Slide",headerText:"Inhale: Dependence",canClose:!1,contentDesign:"tight",contents:["Receive God's forgiveness and walk in the Spirit's power.",{type:"ScrRangeDisplay",reference:"Ephesians 5:18",style:{alignSelf:"flex-start",fontStyle:"italic"}},{type:"ScrRangeDisplay",reference:"1 John 5:14-15",style:{alignSelf:"flex-start",fontStyle:"italic"}},"Thank God for His grace, forgiveness, and indwelling Spirit.","Choose to walk attentively, responding to the Spirit's leading."]}]}]},{id:"Prayer",type:"ContentListScreen",contents:[{type:"Header"},{type:"ActionButton",text:{text:"Opening Reflection"},action:{type:"navigate",to:"OpeningReflection"}},{type:"ActionButton",text:{text:"Why Should We Pray?"},action:{type:"navigate",to:"WhyShouldWePray"}},{type:"ActionButton",text:{text:"Does God Answer Prayer?"},action:{type:"navigate",to:"DoesGodAnswerPrayer"}},{type:"ActionButton",text:{text:"Half-way Recap"},action:{type:"navigate",to:"PrayerHalfwayRecap"}},{type:"ActionButton",text:{text:"How Should We Pray?"},action:{type:"navigate",to:"HowShouldWePray"}},{type:"ActionButton",text:{text:"Jesus' Model for Prayer"},action:{type:"navigate",to:"JesusModelPrayer"}},{type:"ActionButton",text:{text:"Growing in Dependence Through Prayer"},action:{type:"navigate",to:"GrowingDependencePrayer"}}],subscreens:[{id:"OpeningReflection",title:"Opening Reflection",type:"ContentListScreen",contents:[{type:"Header"},{type:"Slide",canClose:!1,contentDesign:"tight",contents:["Prayer is not meant to be complicated. It can be deep or simple, structured or spontaneous, emotional or quiet. At its core, prayer is conversation with God.","People pray in many different ways. Some keep prayer lists to stay focused and remember specific needs. Others use simple frameworks like A.C.T.S. (Adoration, Confession, Thanksgiving, Supplication). Some find it helpful to read written prayers from Scripture, tradition, or trusted voices in the faith. Personally, I often journal my prayers. Writing helps untangle my thoughts and gives me something to return to later, where I can see how God has been faithful over time.","The point is not finding the \"right\" method. There is no formula to master and no perfect wording required. God already knows your heart. Prayer is not performance; it is relationship. God invites honesty. Doubt, frustration, silence, gratitude, and praise all belong in prayer.",{type:"Text",text:"",segments:[{text:"Just as conversations with people take many forms, so do conversations with God. Sometimes prayer is a deep heart-to-heart. Other times it is brief, informal, or even messy. Real relationships are not one-dimensional, and prayer does not need to look the same every day. God is far more concerned "},{text:"that",style:{fontStyle:"italic",textDecorationLine:"underline"}},{text:" you talk with Him than with "},{text:"how",style:{fontStyle:"italic",textDecorationLine:"underline"}},{text:" you do it."}]},"And like any real conversation, prayer also involves listening."]},{type:"QuestionPrompt",text:"What tends to shape your prayer life more right now: routine, emotion, need, or silence?"}]},{id:"WhyShouldWePray",title:"Why Should We Pray?",type:"ContentListScreen",contents:[{type:"Header"},{type:"Slide",canClose:!1,contentDesign:"tight",contents:["Scripture consistently shows prayer as central to life with God."]},{type:"ScriptureQuestionList",question:"Why should we pray?",slides:[{scripture:{reference:"John 16:23-24",revealedButton:{text:"Jesus connects prayer with fullness of joy."}}},{scripture:{reference:"Philippians 4:6-7",revealedButton:{text:"Prayer replaces anxiety with God's peace."}}},{scripture:{reference:"Hebrews 4:14-16",revealedButton:{text:"Jesus understands our weakness and invites us to approach God with confidence."}}},{scripture:{reference:"James 5:16",revealedButton:{text:"Prayer includes confession, community, and healing."}}},{scripture:{reference:"Exodus 32:11-14",revealedButton:{text:"Prayer does not change God's character, but at times God chooses to work through prayer to accomplish His purposes. Scripture shows God inviting His people into real participation, not passive observation."}}},{scripture:{reference:"Luke 22:41-42",revealedButton:{text:"Prayer aligns our hearts with God's will, even when obedience is costly."}}}]},{type:"QuestionPrompt",text:"Which of these reasons for prayer feels most compelling to you right now?"}]},{id:"DoesGodAnswerPrayer",title:"Does God Answer Prayer?",type:"ContentListScreen",contents:[{type:"Header"},{type:"ScriptureQuestionList",question:"Does God answer prayer?",slides:[{scripture:{reference:"1 John 5:14",revealedButton:{text:"God hears prayers that align with His will."}}},{scripture:{reference:"John 14:13",revealedButton:{text:"Praying in Jesus' name means praying in line with His character, mission, and purposes, not using His name as a formula."}}},{scripture:{reference:"James 4:3",revealedButton:{text:"God does not promise to answer prayers driven by selfish desire."}}},{scripture:{reference:"2 Corinthians 12:8-10",revealedButton:{text:"Sometimes God's answer is \"no,\" not because He is distant, but because He is doing something deeper than we can see. God's grace is not proven by the absence of weakness, but by His presence within it."}}}]},{type:"QuestionPrompt",text:"How do you typically respond when God's answer to prayer is unclear or different than what you hoped for?"}]},{id:"PrayerHalfwayRecap",title:"Half-way Recap",type:"ContentListScreen",contents:[{type:"Header"},{type:"Slide",canClose:!1,contentDesign:"tight",contents:["Prayer is not about saying the perfect words or following the perfect method. At its core, prayer is ongoing relationship with God. Scripture presents prayer as honest conversation, dependence, worship, confession, and participation in what God is doing."]},{type:"Slide",canClose:!1,contentDesign:"tight",contents:["God invites us to bring real needs, real emotions, and real questions to Him. Sometimes prayer changes our circumstances. Sometimes it changes us. Sometimes the answer is clear, and sometimes it is confusing or delayed. But throughout Scripture, prayer consistently draws people deeper into trust, surrender, and intimacy with God."]},{type:"Slide",canClose:!1,contentDesign:"tight",contents:["Prayer is not primarily about getting everything we want from God. It is about learning to live with God."]}]},{id:"HowShouldWePray",title:"How Should We Pray?",type:"ContentListScreen",contents:[{type:"Header"},{type:"Slide",canClose:!1,contentDesign:"tight",contents:["Scripture gives us guidance without turning prayer into a rigid system."]},{type:"ScriptureQuestionList",question:"How should we pray?",slides:[{scripture:{reference:"Luke 18:9-14",revealedButton:{text:"Prayer is marked by humility, not self-righteousness."}}},{scripture:{reference:"1 Thessalonians 5:17",revealedButton:{text:"Praying continually does not mean nonstop words, but living with ongoing awareness and dependence on God."}}},{scripture:{reference:"Romans 8:26",revealedButton:{text:"When words fail, the Spirit intercedes on our behalf."}}},{scripture:{reference:"Nehemiah 4:9",revealedButton:{text:"Prayer and action belong together."}}},{scripture:{reference:"Matthew 7:7-8",revealedButton:{text:"Asking, seeking, and knocking reflect persistence."}}},{scripture:{reference:"Luke 11:13",revealedButton:{text:"God delights to give the Holy Spirit to those who ask."}}}]},{type:"QuestionPrompt",text:"Which of these descriptions of prayer stretches you the most?"}]},{id:"JesusModelPrayer",title:"Jesus' Model for Prayer",type:"ContentListScreen",contents:[{type:"Header"},{type:"Slide",canClose:!1,contentDesign:"tight",contents:["When Jesus' disciples asked how to pray, He gave them a model, not a script."]},{type:"Slide",headerText:"Matthew 6:9\u201313",canClose:!1,contentDesign:"tight",contents:[{type:"ScrRangeDisplay",reference:"Matthew 6:9-13",style:{alignSelf:"flex-start",fontStyle:"italic"}}]},{type:"Slide",headerText:"Matthew 6:9",canClose:!0,contentDesign:"tight",contents:["Praise God for who He is and honor His holiness."]},{type:"Slide",headerText:"Matthew 6:10",canClose:!0,contentDesign:"tight",contents:["Align your desires with God's purposes and submit to His will."]},{type:"Slide",headerText:"Matthew 6:11",canClose:!0,contentDesign:"tight",contents:["Bring daily needs honestly before God."]},{type:"Slide",headerText:"Matthew 6:12",canClose:!0,contentDesign:"tight",contents:["Confess sin and extend forgiveness to others."]},{type:"Slide",headerText:"Matthew 6:13",canClose:!0,contentDesign:"tight",contents:["Ask for strength, guidance, and protection from temptation."]},{type:"QuestionPrompt",text:"Which part of Jesus' model prayer do you tend to overlook or rush past?"}]},{id:"GrowingDependencePrayer",title:"Growing in Dependence Through Prayer",type:"ContentListScreen",contents:[{type:"Header"},{type:"Slide",canClose:!1,contentDesign:"tight",contents:["Prayer deepens dependence when it becomes part of everyday life."]},{type:"Slide",headerText:"Make a plan",canClose:!0,contentDesign:"tight",contents:["When will you regularly pray? Consistency matters more than duration."]},{type:"Slide",headerText:"Keep track of prayer requests",canClose:!0,contentDesign:"tight",contents:["Writing prayers down helps you recognize God's faithfulness over time."]},{type:"Slide",headerText:"Practice moment-by-moment prayer",canClose:!0,contentDesign:"tight",contents:["Prayer is not limited to quiet moments alone. Let prayer become your default posture throughout the day."]},{type:"QuestionPrompt",text:"What is one simple step you could take this week to grow in prayer?"}]}]}]},{id:"Resources",type:"ContentListScreen",contents:[{type:"Header"},{type:"ActionButton",text:"Intentionality",action:{type:"navigate",to:"Intentionality"}},{type:"ActionButton",text:"Sample Schedule",action:{type:"navigate",to:"SampleSchedule"}},{type:"ActionButton",text:"Check in Questions",action:{type:"navigate",to:"CheckInQuestions"}}],subscreens:[{id:"Intentionality",type:"ContentListScreen",contents:[{type:"Header",subheaderText:"A tool for finding the right next step of intentionality with people in your life.",lineTexts:["Important conversations rarely happen by accident. Someone has to take the first step.","Intentionality means paying attention to the people God has placed in your life and choosing to take a specific next step with them. You can't control the outcome, but you can choose to be intentional."],design:"screen"},{type:"Slide",headerText:"How to use this tool",canClose:!1,contentDesign:"tight",contents:[]},{type:"Slide",headerText:"1. Identify one person.",canClose:!0,contentDesign:"tight",contents:["Think about the people God has already placed in your life. Which category best describes where your relationship with someone is right now?","Beginning a Relationship","Building the Relationship","Getting to the Gospel","Helping Them Grow","If no one comes to mind, start with Beginning a Relationship and identify someone new you can get to know."]},{type:"Slide",headerText:"2. Choose one next step.",canClose:!0,contentDesign:"tight",contents:["Look through the options in that category. What is one specific step you can take with that person this week?","Don't try to do everything. Choose one step and take it."]},{type:"Slide",headerText:"3. Take the step.",canClose:!0,contentDesign:"tight",contents:["Pray for the person, take the step, and trust God with the outcome. The goal isn't to force a relationship or conversation. It's simply to be faithful with the opportunity God has given you."]},{type:"Slide",headerText:"4. Come back and evaluate.",canClose:!0,contentDesign:"tight",contents:["When we meet again, talk about how it went.","What happened?","What did you learn?","What might be the next right step?","Then choose another step and keep going."]},{type:"Slide",canClose:!1,contentDesign:"tight",contents:["Intentionality is simply taking the next faithful step with the people God has placed in your life."]},{type:"ActionButton",text:"1. Beginning a Relationship",action:{type:"navigate",to:"IntentionalityBeginning"}},{type:"ActionButton",text:"2. Building the Relationship",action:{type:"navigate",to:"IntentionalityBuilding"}},{type:"ActionButton",text:"3. Getting to the Gospel",action:{type:"navigate",to:"IntentionalityGospel"}},{type:"ActionButton",text:"4. Helping Them Grow",action:{type:"navigate",to:"IntentionalityGrowth"}}],subscreens:[{id:"IntentionalityBeginning",title:"1. Beginning a Relationship",type:"ContentListScreen",contents:[{type:"Header"},{type:"Slide",headerText:"Identify who God may be putting in front of you",canClose:!0,contentDesign:"tight",contents:["You don't have to look far. The people you already see regularly are often the best place to start.","Maybe someone who lives down the hall, someone you sit next to in class, a coworker at your campus job, or someone you see at the gym or dining hall.",{type:"NextSteps",steps:["Write down 2\u20133 names","Choose one person to be intentional with this week"]}]},{type:"Slide",headerText:"Pay attention to the people around you",canClose:!0,contentDesign:"tight",contents:["It's easy to move through campus focused on your schedule and miss the people around you.","Think about walking to class, sitting before a lecture starts, waiting in line for coffee, or studying in common areas.",{type:"NextSteps",steps:["Put your phone away in one setting this week","Start one simple conversation \u201cHow's your week going?\u201d"]}]},{type:"Slide",headerText:"Move beyond surface-level conversations",canClose:!0,contentDesign:"tight",contents:["Most relationships stay shallow because no one takes the first step deeper.","Instead of just talking about classes, sports, or weekend plans, you could ask about their major choice, family, goals, or what's been stressful lately.",{type:"NextSteps",steps:["Ask one deeper question this week","Share something a little more personal about yourself"]}]}]},{id:"IntentionalityBuilding",title:"2. Building the Relationship",type:"ContentListScreen",contents:[{type:"Header"},{type:"Slide",headerText:"Spend intentional time together",canClose:!0,contentDesign:"tight",contents:["Relationships grow through time together, not just passing conversations.","This could look like grabbing coffee between classes, lunch at the dining hall, or studying together.",{type:"NextSteps",steps:["Invite them to coffee or a meal","Follow up if they don't give a clear answer"]}]},{type:"Slide",headerText:"Invite them into your world",canClose:!0,contentDesign:"tight",contents:["You don't need to create something new. Just include them in what you're already doing.","Maybe you're going to a campus event, intramural game, club meeting, church gathering, or just heading to the gym.",{type:"NextSteps",steps:["Text them next time you're going to something","Make it casual and easy to say yes to"]}]},{type:"Slide",headerText:"Step into their world",canClose:!0,contentDesign:"tight",contents:["Saying yes to their invitations builds trust and shows you care about what they care about.","This could be going to a club meeting they're part of, a game they're watching, an open mic night, or hanging out with their friend group.",{type:"NextSteps",steps:["Say yes to one invitation this week","Ask what they enjoy doing and join them"]}]},{type:"Slide",headerText:"Open the door to spiritual conversations",canClose:!0,contentDesign:"tight",contents:["You don't have to force it. Small steps can naturally introduce spiritual topics.","This might be when they share something stressful, talk about family, or mention something meaningful going on in their life.",{type:"NextSteps",steps:["Ask, \u201cHow can I pray for you?\u201d","Follow up later and ask how things are going"]}]},{type:"Slide",headerText:"Prioritize consistency over intensity",canClose:!0,contentDesign:"tight",contents:["One long hangout is great, but consistent time together builds stronger relationships.","Think weekly meals, regular study sessions, or quick check-ins between classes.",{type:"NextSteps",steps:["Plan one consistent touchpoint each week","Send a quick text to stay connected"]}]}]},{id:"IntentionalityGospel",title:"3. Getting to the Gospel",type:"ContentListScreen",contents:[{type:"Header"},{type:"Slide",headerText:"Be open about your faith",canClose:!0,contentDesign:"tight",contents:["Talking about your faith doesn't have to feel forced. It can come up naturally as part of your life.","You might mention something from church, a conversation from Bible study, or something you've been thinking about spiritually.",{type:"NextSteps",steps:["Share one personal faith-related thought","Mention a spiritual activity you're part of"]}]},{type:"Slide",headerText:"Understand their spiritual background",canClose:!0,contentDesign:"tight",contents:["Before sharing what you believe, take time to understand their story.","They may have grown up in church, another religion, or with no spiritual background at all.",{type:"NextSteps",steps:["Ask, \u201cDid you grow up around church or faith at all?\u201d","Listen without correcting"]}]},{type:"Slide",headerText:"Explore what they believe now",canClose:!0,contentDesign:"tight",contents:["People often have evolving or mixed beliefs.","They might say they're spiritual, unsure, skeptical, or just haven't thought about it much.",{type:"NextSteps",steps:["Ask, \u201cWhat do you believe about God?\u201d","Ask follow-up questions to understand"]}]},{type:"Slide",headerText:"Invite them to experience Christian community",canClose:!0,contentDesign:"tight",contents:["Seeing faith lived out in community can be powerful.","This could be a campus ministry gathering, church service, small group, or special event.",{type:"NextSteps",steps:["Invite them to something you already attend","Sit with them and talk about it afterward"]}]},{type:"Slide",headerText:"Clearly share the gospel",canClose:!0,contentDesign:"tight",contents:["At some point, it's important to clearly explain who Jesus is and what He has done.","This might come up during a deeper conversation, after they ask questions, or when talking about purpose, sin, or forgiveness.",{type:"NextSteps",steps:["Share a simple version of the gospel","Ask what they think about it"]}]},{type:"Slide",headerText:"Engage their questions and barriers",canClose:!0,contentDesign:"tight",contents:["Doubts are normal and often take time to work through.","They may struggle with things like suffering, hypocrisy in the church, science, or past experiences.",{type:"NextSteps",steps:["Ask, \u201cWhat makes that hard to believe?\u201d","Keep the conversation going over time"]}]},{type:"Slide",headerText:"Keep growing in your ability to share",canClose:!0,contentDesign:"tight",contents:["You don't need to have all the answers, but you can keep learning.","This could look like learning how to explain the gospel clearly or thinking through common questions.",{type:"NextSteps",steps:["Look up one question you didn't know how to answer","Ask a mentor or leader for help"]}]}]},{id:"IntentionalityGrowth",title:"4. Helping Them Grow",type:"ContentListScreen",contents:[{type:"Header"},{type:"Slide",headerText:"Help them build consistent habits",canClose:!0,contentDesign:"tight",contents:["New faith needs structure to grow.","This could be reading the Bible together, praying, or talking through questions regularly.",{type:"NextSteps",steps:["Set a weekly time to meet","Start reading a short passage together"]}]},{type:"Slide",headerText:"Invite them into discipleship",canClose:!0,contentDesign:"tight",contents:["Growth happens best in intentional relationships.","This could be meeting one-on-one or in a small group to learn how to follow Jesus.",{type:"NextSteps",steps:["Ask if they want to meet regularly","Start simple and be consistent"]}]},{type:"Slide",headerText:"Connect them to community",canClose:!0,contentDesign:"tight",contents:["They need more than just you to grow long-term.","This could be your friend group, a small group, or a campus ministry.",{type:"NextSteps",steps:["Introduce them to other believers","Bring them into group settings"]}]},{type:"Slide",headerText:"Plug them into a Bible study",canClose:!0,contentDesign:"tight",contents:["Learning alongside others helps reinforce truth and build friendships.","This might be a dorm Bible study, campus ministry group, or church small group.",{type:"NextSteps",steps:["Invite them to your group","Help them find one that fits"]}]},{type:"Slide",headerText:"Invite them into mission",canClose:!0,contentDesign:"tight",contents:["Growth deepens when they begin living it out themselves.","They could start inviting friends, sharing their story, or joining you in investing in someone else.",{type:"NextSteps",steps:["Bring them along as you meet with someone","Encourage them to take one step with a friend"]}]}]}]},{id:"SampleSchedule",title:"Discipleship Sample Schedule",type:"ContentListScreen",contents:[{type:"Header",lineTexts:["The following is an EXAMPLE schedule. Hopefully, this shows you how to fit Content, Training, Ministry, and Relational Time all within one semester."],design:"screen"},{type:"ScheduleTable",headers:["Week","Main Focus","Notes"],rows:[{week:"1",focus:"The Challenge",notes:"Download TD app and do Challenge to Discipleship"},{week:"2",focus:"Why use TD",notes:"Talk through the purpose and structure of Transferable Discipleship."},{week:"3",focus:{text:"TD #1 (Gospel Review)",bold:!0},notes:"Can break this up into 2 parts"},{week:"4",focus:{text:"TD #1 (Gospel Review)",bold:!0},notes:"If broken up into 2 parts"},{week:"5",focus:"KGP Training",notes:{text:"Godtools is a great app to introduce",italic:!0}},{week:"6",focus:{text:"TD #2 (Scripture 1.0)",bold:!0},notes:"Can break this up into 2 parts"},{week:"7",focus:{text:"TD #2 (Scripture 1.0)",bold:!0},notes:"If broken up into 2 parts"},{week:"8",focus:"Train on evangelism tool (Survey, Solarium, or Perspective Cards)",notes:{text:"Start with what YOU are most comfortable with, but as the semester goes, show them different tools so they can use what THEY are most comfortable with.",italic:!0}},{week:"9",focus:"Quick refresh on evangelism tool then go share.",notes:{text:"Model the tool first then give them a chance to take the lead.",italic:!0}},{week:"10",focus:{text:"TD #3 (Assurance of Salvation)",bold:!0},notes:"Can break this up into 2 parts"},{week:"11",focus:{text:"TD #3 (Assurance of Salvation)",bold:!0},notes:"If broken up into 2 parts"},{week:"12",focus:"Something Fun!",notes:"Find something fun to do together!"},{week:"13",focus:{text:"TD #4 (Holy Spirit)",bold:!0},notes:"Can break this up into 2 parts"},{week:"14",focus:{text:"TD #4 (Holy Spirit)",bold:!0},notes:"If broken up into 2 parts"},{week:"15",focus:"Train on new \"tool\" and then go sharing!",notes:"Introduce another ministry tool and immediately practice using it together."},{week:"16",focus:{text:"TD #5 (Prayer)",bold:!0},notes:"Can break this up into 2 parts"},{week:"17",focus:{text:"TD #5 (Prayer)",bold:!0},notes:"If broken up into 2 parts"},{week:"18",focus:"Prayer Walk",notes:"Spend time praying together around campus"},{week:"19",focus:{text:"TD Intentionality",bold:!0},notes:"A tool for finding the right next step of intentionality with people in your life."}]}]},{id:"CheckInQuestions",title:"Check In Questions",type:"ContentListScreen",contents:[{type:"Header",subheaderText:"These are options of check in questions you could use. Changing up which questions you use each time can be helpful.",design:"screen"},{type:"ActionButton",text:"PERMS (Scale of 1-5)",action:{type:"navigate",to:"CheckInQuestionsPERMS"}},{type:"ActionButton",text:"Something\u2026",action:{type:"navigate",to:"CheckInQuestionsSomething"}},{type:"ActionButton",text:"This last week",action:{type:"navigate",to:"CheckInQuestionsLastWeek"}},{type:"ActionButton",text:"What has God been doing",action:{type:"navigate",to:"CheckInQuestionsGodDoing"}},{type:"ActionButton",text:"What's in your cup?",action:{type:"navigate",to:"CheckInQuestionsCup"}}],subscreens:[{id:"CheckInQuestionsPERMS",title:"Check In Questions",type:"ContentListScreen",contents:[{type:"Header",headerText:"PERMS (Scale of 1\u20135)"},{type:"Slide",headerText:"How are you doing PHYSICALLY?",canClose:!0,contentDesign:"tight",contents:["Use a scale from 1 to 5 (for example: 1 = struggling, 5 = doing great)."]},{type:"Slide",headerText:"How are you doing EMOTIONALLY?",canClose:!0,contentDesign:"tight",contents:["Use a scale from 1 to 5 (for example: 1 = struggling, 5 = doing great)."]},{type:"Slide",headerText:"How are you doing RELATIONALLY?",canClose:!0,contentDesign:"tight",contents:["Use a scale from 1 to 5 (for example: 1 = struggling, 5 = doing great)."]},{type:"Slide",headerText:"How are you doing MENTALLY?",canClose:!0,contentDesign:"tight",contents:["Use a scale from 1 to 5 (for example: 1 = struggling, 5 = doing great)."]},{type:"Slide",headerText:"How are you doing SPIRITUALLY?",canClose:!0,contentDesign:"tight",contents:["Use a scale from 1 to 5 (for example: 1 = struggling, 5 = doing great)."]}]},{id:"CheckInQuestionsSomething",title:"Check In Questions",type:"ContentListScreen",contents:[{type:"Header",headerText:"Something\u2026."},{type:"Slide",headerText:"What was something this past week that was ENCOURAGING?",canClose:!1,contentDesign:"tight",contents:[]},{type:"Slide",headerText:"What was something this past week that was HARD/DISCOURAGING?",canClose:!1,contentDesign:"tight",contents:[]},{type:"Slide",headerText:"What was something this past week that was FUN?",canClose:!1,contentDesign:"tight",contents:[]},{type:"Slide",headerText:"What was something this past week from your QT (time with the Lord?)",canClose:!1,contentDesign:"tight",contents:[]}]},{id:"CheckInQuestionsLastWeek",title:"Check In Questions",type:"ContentListScreen",contents:[{type:"Header",headerText:"This last week"},{type:"Slide",headerText:"This last week- what has been something\u2026..",canClose:!1,contentDesign:"tight",contents:[]},{type:"Slide",headerText:"Fun",canClose:!1,contentDesign:"tight",contents:[]},{type:"Slide",headerText:"Hard",canClose:!1,contentDesign:"tight",contents:[]},{type:"Slide",headerText:"Restful",canClose:!1,contentDesign:"tight",contents:[]},{type:"Slide",headerText:"Stressful",canClose:!1,contentDesign:"tight",contents:[]}]},{id:"CheckInQuestionsGodDoing",title:"Check In Questions",type:"ContentListScreen",contents:[{type:"Header",headerText:"What has God been doing"},{type:"Slide",headerText:"What has God been doing in you?",canClose:!1,contentDesign:"tight",contents:[]},{type:"Slide",headerText:"What has God been doing around you?",canClose:!1,contentDesign:"tight",contents:[]},{type:"Slide",headerText:"What has God been doing through you?",canClose:!1,contentDesign:"tight",contents:[]}]},{id:"CheckInQuestionsCup",title:"Check In Questions",type:"ContentListScreen",contents:[{type:"Header",headerText:"What's in your cup?? (takes some creative juices\u2026..)",subheaderText:"(Ask them to describe what kind of beverage and how full the cup is.)",design:"screen"},{type:"Slide",headerText:"Physical Cup",canClose:!1,contentDesign:"tight",contents:[]},{type:"Slide",headerText:"Emotional Cup",canClose:!1,contentDesign:"tight",contents:[]},{type:"Slide",headerText:"Relational Cup",canClose:!1,contentDesign:"tight",contents:[]},{type:"Slide",headerText:"Mental Cup",canClose:!1,contentDesign:"tight",contents:[]},{type:"Slide",headerText:"Spiritual Cup",canClose:!1,contentDesign:"tight",contents:[]},{type:"Slide",headerText:"EXAMPLE",canClose:!0,contentDesign:"tight",contents:["My physical cup is \xbd full of unsweet tea\u2014I have a cold/a little sick. I can still function ok, and get by, but it isn\u2019t wonderful.","My spiritual cup is full of water. I\u2019m doing it like I should be, and it\u2019s good for me, but I am not enjoying the flavor."]}]}]}]},{id:"About",type:"ContentListScreen",design:"tight",contents:[{type:"Header",headerText:"About Transferable Discipleship",lineTexts:["Transferable Discipleship is a tool for Simple, Accessible, and Transferable Christian discipleship."],design:"screen"},{type:"Slide",headerText:{text:"Dark Mode",style:{color:"#9c9fa1"}},contentDesign:"tight",contents:[{type:"DarkModeToggle"}]},{type:"Slide",headerText:{text:"Reset Progress",style:{color:"#9c9fa1"}},contentDesign:"tight",contents:["Reset all visited screens to show buttons in their original color.",{type:"ActionButton",text:"Reset Visited Screens",design:"answer",action:{type:"resetVisited"}}]},{type:"Slide",headerText:{text:"Feedback?",style:{color:"#9c9fa1"}},contentDesign:"tight",contents:["Found a problem? Want a feature? Other feedback?",{type:"ActionButton",text:"Let us know",design:"answer",action:{type:"link",to:"https://github.com/tjcouch1/transferable-discipleship/issues"}}]},{type:"Slide",headerText:{text:"Create Your Own Discipleship App",style:{color:"#9c9fa1"}},contentDesign:"tight",contents:["This app was created using discipleship\u2011app\u2011template. Want to make your own discipleship app like this one?",{type:"ActionButton",design:"answer",text:"Fork the template on GitHub!",action:{type:"link",to:"https://github.com/tjcouch1/discipleship%2Dapp%2Dtemplate"}}]},{type:"Slide",headerText:{text:"Credits and Licensing",style:{color:"#9c9fa1"}},contentDesign:"tight",contents:["- Disciple-making content of the app created by Wesley Skinner; edited and implemented by TJ Couch.\n- discipleship\u2011app\u2011template developed by TJ Couch.\n- Scripture quoted from New English Translation (NET).",{type:"ActionButton",design:"answer",text:"More Licensing Info",action:{type:"navigate",to:"Credits"}}]}],subscreens:[{id:"Credits",type:"ContentListScreen",design:"tight",contents:[{type:"Header",headerText:"Credits and Attributions",design:"screen",lineTexts:["Thanks to all the many people who made this app possible."]},{type:"Slide",headerText:"Transferable Discipleship",contentDesign:"tight",contents:["Transferable Discipleship Copyright 2023 Wesley Skinner and TJ Couch.\ntjcouch1@gmail.com\nLicensed under the GPL-3.0-only License.\nMore information on the Software Licenses page linked below."]},{type:"Slide",headerText:"Discipleship\u2004App\u2004Template",contentDesign:"tight",contents:["This app was created using discipleship\u2011app\u2011template Copyright 2023 TJ Couch.\ntjcouch1@gmail.com\nLicensed under the GPL-3.0-only License.\nMore information on the Software Licenses page linked below."]},{type:"Slide",headerText:"New English Translation",contentDesign:"tight",contents:["The Scripture included in this app is from the New English Translation. Scripture data retrieved and cached from AO Lab's bible-api.pages.dev. Scripture quoted by permission. Quotations designated (NET) are from the NET Bible\xae copyright \xa91996, 2019 by Biblical Studies Press, L.L.C. https://netbible.com All rights reserved.",{type:"ActionButton",design:"answer",text:"netbible.com",action:{type:"link",to:"https://netbible.com/"}}]},{type:"Slide",headerText:"Fonts",contentDesign:"tight",contents:["- Libre Franklin is licensed under the SIL Open Font License Version 1.1.\nMore information on the Software Licenses page linked below.",{type:"ActionButton",design:"answer",text:"Libre Franklin GitHub",action:{type:"link",to:"https://github.com/impallari/Libre-Franklin"}},"- Open Sauce One is licensed under the SIL Open Font License Version 1.1.\nMore information on the Software Licenses page linked below.",{type:"ActionButton",design:"answer",text:"Open Sauce GitHub",action:{type:"link",to:"https://github.com/marcologous/Open-Sauce-Fonts"}}]},{type:"Slide",headerText:"Privacy Policy",contentDesign:"tight",contents:["We intend to take and keep as little information about you as possible; we have no interest in your personal information. Privacy policy generated with the help of Termly. View our privacy policy here:",{type:"ActionButton",design:"answer",text:"Privacy Policy",action:{type:"link",to:"https://tjcouch1.github.io/transferable-discipleship/privacy-policy.html"}},"On opening the app, the app will send an HTTPS request to a remote server to check for updates. It will share only information relevant to receiving updates like operating system. This service is provided by Expo. See more information here:",{type:"ActionButton",design:"answer",text:"Expo Privacy Policy",action:{type:"link",to:"https://expo.dev/privacy-explained#expo-and-end-user-data"}}]},{type:"Slide",headerText:"Software Licenses",contentDesign:"tight",contents:["This software was created using many amazing libraries including React Native and Expo. Beware there are many licenses to display on the following page. It will take a long time to load.",{type:"ActionButton",design:"answer",text:"Software License Info",action:{type:"navigate",to:"app:/__licenses"}}]}]}]}]}]}},441,[]);
